-- ============================================================================
--  Day Webster — Candidate Pipeline · Mandatory Training: DRAFT authoring seed
--  File: candidate-pipeline/sql/53_training_seed_full.sql
--  Run AFTER 47–52.  Idempotent.  STATUS: DRAFT — NOT YET APPLIED.
--
--  ┌────────────────────────────────────────────────────────────────────────┐
--  │  AI-DRAFTED SCAFFOLDING — NOT ACCREDITED, NOT PUBLISHED.                 │
--  │  Every module here is a DRAFT requiring SME review + manager approval    │
--  │  before it can be assigned. Content is CSTF-aligned draft, not           │
--  │  authoritative; verify against the current Skills for Health CSTF        │
--  │  Subject Guide and your accreditation.                                   │
--  └────────────────────────────────────────────────────────────────────────┘
--
--  52 seeded 14 modules but FULLY AUTHORED + PUBLISHED only 2
--  (moving_handling_l2, ipc_l2). This file drafts KB content + a question bank
--  for the other 12 catalogue-only modules so the SME starts from a draft, not
--  a blank page — the "AI drafts -> human approves" pipeline.
--
--  What this does per module (12 modules):
--    1. Creates ONE module_versions row (version 1) via save_module_version:
--       status='draft', ai_generated=true, ai_model='claude-opus-4-8', with a
--       few CSTF-aligned KB sections. It is NOT submitted, NOT approved, NOT
--       published; training_modules.current_version_id is untouched (stays NULL).
--    2. Appends 12–15 single-best-answer MCQs via add_training_question so the
--       bank exceeds question_count (10) and is publishable AFTER SME review.
--
--  Idempotency: each module is guarded by NOT EXISTS (any module_versions row
--  for that module). save_module_version always creates version max+1, so the
--  guard is what makes a re-run a clean no-op — and it also means the 2 modules
--  authored in 52 (which already have a version) are never touched here.
--
--  Honesty: these are DRAFTS. No fabricated statistics or fake citations — only
--  well-established CSTF learning points. Every period/level/answer remains an
--  editable default pending named-SME sign-off (see 47 header + 52 +
--  TRAINING_CSTF_RESEARCH.md).
-- ============================================================================

-- ── 1. Equality, Diversity & Human Rights ────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'equality_diversity_hr';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Equality, Diversity and Human Rights for all health and care staff. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited."},
      {"heading":"The Equality Act 2010","body_md":"The Equality Act 2010 protects people from discrimination in the workplace and in wider society. It defines nine protected characteristics: age, disability, gender reassignment, marriage and civil partnership, pregnancy and maternity, race, religion or belief, sex, and sexual orientation."},
      {"heading":"Types of discrimination","body_md":"Direct discrimination is treating someone less favourably because of a protected characteristic. Indirect discrimination is a policy that applies to everyone but disadvantages a protected group. Harassment is unwanted conduct that violates dignity or creates a hostile environment. Victimisation is treating someone badly because they made or supported a complaint about discrimination."},
      {"heading":"Human rights","body_md":"The Human Rights Act 1998 brings the European Convention on Human Rights into UK law. In care the FREDA principles are a useful guide: Fairness, Respect, Equality, Dignity and Autonomy. Rights must be balanced and applied to every person you support."},
      {"heading":"Applying it in practice","body_md":"Make reasonable adjustments so disabled people are not disadvantaged. Provide person-centred, inclusive care that respects individual needs, beliefs and communication preferences. If you witness discrimination, harassment or bullying, challenge it where safe and report it through your organisation's policy — inaction is not neutral."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"How many protected characteristics are defined by the Equality Act 2010?","options":[{"key":"a","text":"Five"},{"key":"b","text":"Seven"},{"key":"c","text":"Nine"},{"key":"d","text":"Twelve"}],"correct_keys":["c"],"explanation":"The Equality Act 2010 defines nine protected characteristics.","sort_order":10},
      {"stem":"Which of the following IS a protected characteristic under the Equality Act 2010?","options":[{"key":"a","text":"Job title"},{"key":"b","text":"Religion or belief"},{"key":"c","text":"Postcode"},{"key":"d","text":"Hair colour"}],"correct_keys":["b"],"explanation":"Religion or belief is one of the nine protected characteristics.","sort_order":20},
      {"stem":"Which of the following is NOT a protected characteristic?","options":[{"key":"a","text":"Age"},{"key":"b","text":"Sexual orientation"},{"key":"c","text":"Social class"},{"key":"d","text":"Disability"}],"correct_keys":["c"],"explanation":"Social class is not one of the nine protected characteristics.","sort_order":30},
      {"stem":"Treating someone less favourably because of a protected characteristic is:","options":[{"key":"a","text":"Direct discrimination"},{"key":"b","text":"Indirect discrimination"},{"key":"c","text":"Victimisation"},{"key":"d","text":"Positive action"}],"correct_keys":["a"],"explanation":"Direct discrimination is less favourable treatment because of a protected characteristic.","sort_order":40},
      {"stem":"A rule that applies to everyone but puts a protected group at a disadvantage is:","options":[{"key":"a","text":"Direct discrimination"},{"key":"b","text":"Indirect discrimination"},{"key":"c","text":"Harassment"},{"key":"d","text":"Victimisation"}],"correct_keys":["b"],"explanation":"Indirect discrimination is a neutral-looking policy that disadvantages a protected group.","sort_order":50},
      {"stem":"Unwanted conduct that violates a person's dignity or creates a hostile environment is:","options":[{"key":"a","text":"Victimisation"},{"key":"b","text":"Harassment"},{"key":"c","text":"A reasonable adjustment"},{"key":"d","text":"Positive action"}],"correct_keys":["b"],"explanation":"That is the legal definition of harassment.","sort_order":60},
      {"stem":"Treating someone badly because they raised a complaint about discrimination is:","options":[{"key":"a","text":"Harassment"},{"key":"b","text":"Indirect discrimination"},{"key":"c","text":"Victimisation"},{"key":"d","text":"Direct discrimination"}],"correct_keys":["c"],"explanation":"Victimisation is detriment for making or supporting a discrimination complaint.","sort_order":70},
      {"stem":"A reasonable adjustment is most closely associated with which protected characteristic?","options":[{"key":"a","text":"Disability"},{"key":"b","text":"Age"},{"key":"c","text":"Race"},{"key":"d","text":"Sex"}],"correct_keys":["a"],"explanation":"Employers and services must make reasonable adjustments so disabled people are not disadvantaged.","sort_order":80},
      {"stem":"Which UK law brings the European Convention on Human Rights into domestic law?","options":[{"key":"a","text":"Care Act 2014"},{"key":"b","text":"Human Rights Act 1998"},{"key":"c","text":"Data Protection Act 2018"},{"key":"d","text":"Mental Capacity Act 2005"}],"correct_keys":["b"],"explanation":"The Human Rights Act 1998 incorporates the ECHR into UK law.","sort_order":90},
      {"stem":"In the FREDA human-rights principles, the 'D' stands for:","options":[{"key":"a","text":"Diversity"},{"key":"b","text":"Dignity"},{"key":"c","text":"Discretion"},{"key":"d","text":"Diligence"}],"correct_keys":["b"],"explanation":"FREDA = Fairness, Respect, Equality, Dignity, Autonomy.","sort_order":100},
      {"stem":"A colleague repeatedly makes racist jokes about a patient. You should:","options":[{"key":"a","text":"Ignore it as it is not your business"},{"key":"b","text":"Laugh along to keep the peace"},{"key":"c","text":"Challenge it where safe and report it through policy"},{"key":"d","text":"Wait to see if anyone else complains"}],"correct_keys":["c"],"explanation":"Discrimination should be challenged where safe and reported; inaction condones it.","sort_order":110},
      {"stem":"Person-centred, inclusive care means:","options":[{"key":"a","text":"Treating everyone in exactly the same way regardless of need"},{"key":"b","text":"Adapting care to the individual's needs, beliefs and preferences"},{"key":"c","text":"Prioritising staff convenience"},{"key":"d","text":"Applying one fixed routine to all patients"}],"correct_keys":["b"],"explanation":"Equality of outcome often requires adjusting care to individual needs, not identical treatment.","sort_order":120},
      {"stem":"Positive action under the Equality Act allows employers to:","options":[{"key":"a","text":"Always give jobs to under-represented groups automatically"},{"key":"b","text":"Take proportionate steps to help disadvantaged or under-represented groups"},{"key":"c","text":"Discriminate freely against any group"},{"key":"d","text":"Ignore protected characteristics entirely"}],"correct_keys":["b"],"explanation":"Positive action permits proportionate measures to address disadvantage; it is not automatic preferential appointment.","sort_order":130},
      {"stem":"Human rights in care must be:","options":[{"key":"a","text":"Applied only to staff"},{"key":"b","text":"Balanced and applied to every person you support"},{"key":"c","text":"Suspended when a ward is busy"},{"key":"d","text":"Decided by seniority"}],"correct_keys":["b"],"explanation":"Rights apply to everyone and must be respected and balanced.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 2. Health, Safety & Welfare ──────────────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'health_safety_welfare';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Health, Safety and Welfare for all health and care staff. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited."},
      {"heading":"The law","body_md":"The Health and Safety at Work etc. Act 1974 is the primary legislation. Employers must, so far as is reasonably practicable, provide a safe workplace, safe systems of work, and information, instruction and training. Employees must take reasonable care of their own and others' safety and co-operate with their employer. Health and safety is a shared responsibility."},
      {"heading":"Hazard, risk and risk assessment","body_md":"A hazard is anything with the potential to cause harm. A risk is the likelihood that harm will occur and how serious it could be. The five steps of risk assessment are: identify the hazards; decide who might be harmed and how; evaluate the risks and decide on controls; record your findings; and review and update."},
      {"heading":"Reporting","body_md":"Report hazards, accidents and near misses promptly so they can be controlled. Certain serious injuries, occupational diseases and dangerous occurrences are reportable under RIDDOR (Reporting of Injuries, Diseases and Dangerous Occurrences Regulations). Hazardous substances are controlled under COSHH (Control of Substances Hazardous to Health)."},
      {"heading":"Controls and welfare","body_md":"Use the hierarchy of controls — eliminate or reduce the risk at source first; personal protective equipment (PPE) is the last resort, not the first. Employers must also manage welfare risks such as work-related stress, lone working and slips, trips and falls."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"What is the primary piece of UK health and safety legislation?","options":[{"key":"a","text":"Health and Safety at Work etc. Act 1974"},{"key":"b","text":"Equality Act 2010"},{"key":"c","text":"Care Act 2014"},{"key":"d","text":"Data Protection Act 2018"}],"correct_keys":["a"],"explanation":"The Health and Safety at Work etc. Act 1974 is the overarching UK law.","sort_order":10},
      {"stem":"Under the Act, employees have a duty to:","options":[{"key":"a","text":"Take reasonable care of their own and others' safety and co-operate"},{"key":"b","text":"Ignore hazards outside their job role"},{"key":"c","text":"Carry out their own risk assessments only"},{"key":"d","text":"Provide their own PPE"}],"correct_keys":["a"],"explanation":"Employees must take reasonable care and co-operate with their employer.","sort_order":20},
      {"stem":"A hazard is best defined as:","options":[{"key":"a","text":"The likelihood that harm will occur"},{"key":"b","text":"Anything with the potential to cause harm"},{"key":"c","text":"An injury that has already happened"},{"key":"d","text":"A type of PPE"}],"correct_keys":["b"],"explanation":"A hazard is anything with the potential to cause harm.","sort_order":30},
      {"stem":"Risk refers to:","options":[{"key":"a","text":"The potential to cause harm"},{"key":"b","text":"The likelihood and severity of harm occurring"},{"key":"c","text":"A hazardous chemical"},{"key":"d","text":"A safe system of work"}],"correct_keys":["b"],"explanation":"Risk is the likelihood that harm will occur and how serious it could be.","sort_order":40},
      {"stem":"What is the FIRST step of a risk assessment?","options":[{"key":"a","text":"Record your findings"},{"key":"b","text":"Identify the hazards"},{"key":"c","text":"Review and update"},{"key":"d","text":"Buy PPE"}],"correct_keys":["b"],"explanation":"The first of the five steps is to identify the hazards.","sort_order":50},
      {"stem":"RIDDOR is concerned with:","options":[{"key":"a","text":"Reporting specified injuries, diseases and dangerous occurrences"},{"key":"b","text":"Data protection"},{"key":"c","text":"Fire evacuation"},{"key":"d","text":"Recruitment checks"}],"correct_keys":["a"],"explanation":"RIDDOR requires reporting of specified injuries, diseases and dangerous occurrences.","sort_order":60},
      {"stem":"COSHH regulations control:","options":[{"key":"a","text":"Manual handling"},{"key":"b","text":"Substances hazardous to health"},{"key":"c","text":"Working time"},{"key":"d","text":"Fire doors"}],"correct_keys":["b"],"explanation":"COSHH = Control of Substances Hazardous to Health.","sort_order":70},
      {"stem":"Whose responsibility is health and safety in the workplace?","options":[{"key":"a","text":"Only the employer"},{"key":"b","text":"Only the health and safety officer"},{"key":"c","text":"Everyone — a shared responsibility"},{"key":"d","text":"Only senior managers"}],"correct_keys":["c"],"explanation":"Health and safety is a shared responsibility of employers and employees.","sort_order":80},
      {"stem":"A 'near miss' is:","options":[{"key":"a","text":"An event that could have caused harm but did not"},{"key":"b","text":"A minor injury that needs no action"},{"key":"c","text":"A fatality"},{"key":"d","text":"Something that never needs reporting"}],"correct_keys":["a"],"explanation":"A near miss could have caused harm and should be reported so the risk is controlled.","sort_order":90},
      {"stem":"You notice a frayed electrical cable you cannot fix. You should:","options":[{"key":"a","text":"Keep using it carefully"},{"key":"b","text":"Take it out of use and report the hazard"},{"key":"c","text":"Wait for someone else to notice"},{"key":"d","text":"Tape over it and continue"}],"correct_keys":["b"],"explanation":"Remove the hazard from use and report it promptly.","sort_order":100},
      {"stem":"In the hierarchy of controls, PPE is:","options":[{"key":"a","text":"The first control to apply"},{"key":"b","text":"The last resort, after other controls"},{"key":"c","text":"Never used in care"},{"key":"d","text":"A substitute for risk assessment"}],"correct_keys":["b"],"explanation":"Eliminate or reduce risk at source first; PPE is the last line of defence.","sort_order":110},
      {"stem":"Work-related stress is:","options":[{"key":"a","text":"Not a health and safety matter"},{"key":"b","text":"A welfare risk the employer must manage"},{"key":"c","text":"Only an individual's problem"},{"key":"d","text":"Reportable under COSHH"}],"correct_keys":["b"],"explanation":"Employers must assess and manage work-related stress as a welfare risk.","sort_order":120},
      {"stem":"A sensible precaution for lone working is to:","options":[{"key":"a","text":"Tell no one your whereabouts"},{"key":"b","text":"Agree a check-in and location plan with a colleague"},{"key":"c","text":"Turn off your phone to save battery"},{"key":"d","text":"Avoid all risk assessment"}],"correct_keys":["b"],"explanation":"Lone workers should have a check-in system and share their location plan.","sort_order":130},
      {"stem":"Recording risk-assessment findings is important because it:","options":[{"key":"a","text":"Is optional paperwork"},{"key":"b","text":"Provides evidence and helps communicate and review controls"},{"key":"c","text":"Replaces the need for controls"},{"key":"d","text":"Is only for the fire officer"}],"correct_keys":["b"],"explanation":"Recording findings evidences the assessment and supports review and communication of controls.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 3. Conflict Resolution ───────────────────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'conflict_resolution';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Conflict Resolution (theory) for patient-facing staff. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited. Any physical intervention or breakaway skills require separate, accredited practical training."},
      {"heading":"Causes and warning signs","body_md":"Conflict in health and care often arises from pain, fear, long waits, alcohol or drugs, mental ill-health, or frustration. Early warning signs of rising aggression include raised voice, clenched fists, invading personal space, tense posture and prolonged staring. Recognising these signs early gives you time to de-escalate."},
      {"heading":"Communication and the attitude cycle","body_md":"Much of communication is non-verbal — tone, facial expression, posture and gestures. Your own attitude and behaviour influence how the other person responds (a cycle of behaviour). Staying calm, open and respectful can defuse a situation, while a defensive or aggressive manner can escalate it."},
      {"heading":"De-escalation","body_md":"Use active listening, a calm and steady tone, open body language and empathy. Acknowledge the person's feelings, avoid confrontation, give them space and time, and do not crowd or corner them. Keep a safe distance and respect personal space."},
      {"heading":"Staying safe and reporting","body_md":"Position yourself with a clear route to an exit and do not let yourself be cornered. If de-escalation fails and you are at risk, remove yourself and summon help — your safety comes first. Physical intervention is a last resort and only if you are trained. Report every incident and access post-incident support and debrief."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"When faced with an angry person, your first priority should be to:","options":[{"key":"a","text":"Win the argument"},{"key":"b","text":"Stay safe and attempt to de-escalate"},{"key":"c","text":"Physically restrain them"},{"key":"d","text":"Raise your voice to take control"}],"correct_keys":["b"],"explanation":"Safety first, then de-escalation.","sort_order":10},
      {"stem":"Which is an early warning sign of escalating aggression?","options":[{"key":"a","text":"Relaxed, open posture"},{"key":"b","text":"Clenched fists and invading personal space"},{"key":"c","text":"Smiling and calm speech"},{"key":"d","text":"Sitting quietly"}],"correct_keys":["b"],"explanation":"Clenched fists and space invasion are recognised warning signs.","sort_order":20},
      {"stem":"Which of these is a common trigger for conflict in healthcare?","options":[{"key":"a","text":"Long waits, pain or fear"},{"key":"b","text":"Comfortable seating"},{"key":"c","text":"Short waiting times"},{"key":"d","text":"Clear signage"}],"correct_keys":["a"],"explanation":"Pain, fear and long waits commonly trigger conflict.","sort_order":30},
      {"stem":"In communication, non-verbal signals such as tone and body language are:","options":[{"key":"a","text":"Unimportant compared with words"},{"key":"b","text":"A major part of how the message is received"},{"key":"c","text":"Only relevant on the phone"},{"key":"d","text":"The same as active listening"}],"correct_keys":["b"],"explanation":"Non-verbal communication carries much of the message.","sort_order":40},
      {"stem":"An effective de-escalation technique is to:","options":[{"key":"a","text":"Interrupt and correct the person"},{"key":"b","text":"Use active listening and a calm, steady tone"},{"key":"c","text":"Stand very close to show authority"},{"key":"d","text":"Match their raised voice"}],"correct_keys":["b"],"explanation":"Active listening and a calm tone help defuse tension.","sort_order":50},
      {"stem":"Regarding personal space during a tense encounter, you should:","options":[{"key":"a","text":"Stand as close as possible"},{"key":"b","text":"Maintain a safe distance and avoid crowding the person"},{"key":"c","text":"Touch them to reassure them"},{"key":"d","text":"Block their exit"}],"correct_keys":["b"],"explanation":"Respect personal space and keep a safe distance.","sort_order":60},
      {"stem":"When positioning yourself in a potentially violent situation you should:","options":[{"key":"a","text":"Keep a clear route to an exit"},{"key":"b","text":"Corner yourself against a wall"},{"key":"c","text":"Stand between the person and the only door"},{"key":"d","text":"Turn your back to them"}],"correct_keys":["a"],"explanation":"Keep a clear escape route and never get cornered.","sort_order":70},
      {"stem":"Your own attitude and behaviour during conflict:","options":[{"key":"a","text":"Have no effect on the other person"},{"key":"b","text":"Can influence whether the situation escalates or calms"},{"key":"c","text":"Only matter if you are a manager"},{"key":"d","text":"Should always be confrontational"}],"correct_keys":["b"],"explanation":"Behaviour breeds behaviour; your manner affects the outcome.","sort_order":80},
      {"stem":"If de-escalation fails and you are at immediate risk, you should:","options":[{"key":"a","text":"Stay and continue arguing"},{"key":"b","text":"Remove yourself from danger and summon help"},{"key":"c","text":"Restrain the person yourself"},{"key":"d","text":"Ignore the threat"}],"correct_keys":["b"],"explanation":"Your safety comes first — withdraw and call for help.","sort_order":90},
      {"stem":"Physical intervention (restraint) should be:","options":[{"key":"a","text":"A first response to any conflict"},{"key":"b","text":"Used only as a last resort and only if trained"},{"key":"c","text":"Used by any member of staff at any time"},{"key":"d","text":"Never documented"}],"correct_keys":["b"],"explanation":"Restraint is a last resort requiring accredited training.","sort_order":100},
      {"stem":"Active listening involves:","options":[{"key":"a","text":"Planning your reply while they talk"},{"key":"b","text":"Giving full attention, acknowledging feelings and clarifying"},{"key":"c","text":"Talking over the person"},{"key":"d","text":"Looking at your phone"}],"correct_keys":["b"],"explanation":"Active listening means attending fully, acknowledging and clarifying.","sort_order":110},
      {"stem":"After a violent or aggressive incident you should:","options":[{"key":"a","text":"Say nothing and carry on"},{"key":"b","text":"Report it and access debrief and support"},{"key":"c","text":"Only tell colleagues informally"},{"key":"d","text":"Wait a week before reporting"}],"correct_keys":["b"],"explanation":"Incidents must be reported, with debrief and support offered.","sort_order":120},
      {"stem":"Recognising warning signs early is valuable because it:","options":[{"key":"a","text":"Guarantees no one will be harmed"},{"key":"b","text":"Gives time to de-escalate before aggression peaks"},{"key":"c","text":"Means restraint should be used immediately"},{"key":"d","text":"Removes the need to report"}],"correct_keys":["b"],"explanation":"Early recognition creates time to intervene calmly.","sort_order":130},
      {"stem":"Empathy in de-escalation means:","options":[{"key":"a","text":"Agreeing to unreasonable demands"},{"key":"b","text":"Acknowledging the person's feelings without necessarily agreeing"},{"key":"c","text":"Telling them they are wrong"},{"key":"d","text":"Ignoring how they feel"}],"correct_keys":["b"],"explanation":"Acknowledging feelings helps the person feel heard and lowers tension.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 4. Fire Safety ───────────────────────────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'fire_safety';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Fire Safety for health and care staff. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited. Know your local fire evacuation procedure and assembly point."},
      {"heading":"The law and the fire triangle","body_md":"The Regulatory Reform (Fire Safety) Order 2005 is the main fire safety law in England and Wales; it requires a fire risk assessment and a responsible person. Fire needs three things — heat, fuel and oxygen (the fire triangle). Removing any one puts the fire out."},
      {"heading":"Prevention","body_md":"Most fires are preventable. Good housekeeping reduces combustible material and keeps escape routes clear. Do not overload sockets, report faulty electrical equipment, and keep fire doors closed. Fire doors must never be wedged or propped open."},
      {"heading":"If you discover a fire — RACE","body_md":"Follow RACE: Rescue anyone in immediate danger if safe to do so; raise the Alarm; Confine the fire by closing doors and windows; and Evacuate (or attempt to Extinguish only if trained and it is safe). Never use lifts during a fire — use the stairs."},
      {"heading":"Extinguishers and evacuation","body_md":"Extinguishers are colour-coded: water (red) for wood/paper but NOT electrical or fat fires; foam (cream); CO2 (black) for electrical; dry powder (blue); wet chemical (yellow) for cooking oils. Operate with PASS: Pull, Aim, Squeeze, Sweep. Smoke and toxic gases, not flames, cause most fire deaths, so keep low and get out. People needing help to evacuate should have a Personal Emergency Evacuation Plan (PEEP)."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"The three elements of the fire triangle are:","options":[{"key":"a","text":"Heat, fuel and oxygen"},{"key":"b","text":"Smoke, spark and wind"},{"key":"c","text":"Water, foam and powder"},{"key":"d","text":"Heat, light and sound"}],"correct_keys":["a"],"explanation":"Fire needs heat, fuel and oxygen.","sort_order":10},
      {"stem":"The main fire safety legislation in England and Wales is:","options":[{"key":"a","text":"Regulatory Reform (Fire Safety) Order 2005"},{"key":"b","text":"Health and Safety at Work etc. Act 1974"},{"key":"c","text":"Care Act 2014"},{"key":"d","text":"Fire Extinguisher Act 1999"}],"correct_keys":["a"],"explanation":"The Regulatory Reform (Fire Safety) Order 2005 is the governing law.","sort_order":20},
      {"stem":"On discovering a fire, your priority action is to:","options":[{"key":"a","text":"Find an extinguisher first"},{"key":"b","text":"Raise the alarm"},{"key":"c","text":"Collect your belongings"},{"key":"d","text":"Investigate the source"}],"correct_keys":["b"],"explanation":"Raise the alarm so everyone is warned and help is summoned.","sort_order":30},
      {"stem":"In the RACE procedure, the 'C' stands for:","options":[{"key":"a","text":"Call the manager"},{"key":"b","text":"Confine the fire (close doors and windows)"},{"key":"c","text":"Collect equipment"},{"key":"d","text":"Continue working"}],"correct_keys":["b"],"explanation":"RACE = Rescue, Alarm, Confine, Evacuate/Extinguish.","sort_order":40},
      {"stem":"A water (red) extinguisher must NOT be used on:","options":[{"key":"a","text":"Wood and paper fires"},{"key":"b","text":"Electrical or fat/oil fires"},{"key":"c","text":"Textile fires"},{"key":"d","text":"Cardboard fires"}],"correct_keys":["b"],"explanation":"Water conducts electricity and spreads fat fires — never use it on those.","sort_order":50},
      {"stem":"Which extinguisher is suitable for electrical fires?","options":[{"key":"a","text":"Water (red)"},{"key":"b","text":"CO2 (black)"},{"key":"c","text":"Wet chemical (yellow)"},{"key":"d","text":"Foam (cream)"}],"correct_keys":["b"],"explanation":"CO2 (black) is suitable for electrical fires.","sort_order":60},
      {"stem":"Fire doors should be:","options":[{"key":"a","text":"Wedged open for convenience"},{"key":"b","text":"Kept closed (never propped open)"},{"key":"c","text":"Removed to improve airflow"},{"key":"d","text":"Locked at all times"}],"correct_keys":["b"],"explanation":"Fire doors must be kept closed to contain fire and smoke.","sort_order":70},
      {"stem":"During evacuation from a building on fire you should:","options":[{"key":"a","text":"Use the lift to be quicker"},{"key":"b","text":"Use the stairs, never the lift"},{"key":"c","text":"Go back for belongings"},{"key":"d","text":"Open windows to let smoke out as you leave"}],"correct_keys":["b"],"explanation":"Never use lifts in a fire; use the stairs.","sort_order":80},
      {"stem":"What causes most deaths in fires?","options":[{"key":"a","text":"Direct contact with flames"},{"key":"b","text":"Smoke and toxic gases"},{"key":"c","text":"Falling debris"},{"key":"d","text":"Extinguisher misuse"}],"correct_keys":["b"],"explanation":"Smoke inhalation and toxic gases cause most fire deaths.","sort_order":90},
      {"stem":"The PASS technique for using an extinguisher stands for:","options":[{"key":"a","text":"Pull, Aim, Squeeze, Sweep"},{"key":"b","text":"Push, Alarm, Stop, Shout"},{"key":"c","text":"Point, Assess, Spray, Stand"},{"key":"d","text":"Pull, Alert, Spray,Shut"}],"correct_keys":["a"],"explanation":"PASS = Pull the pin, Aim, Squeeze, Sweep.","sort_order":100},
      {"stem":"A PEEP is a:","options":[{"key":"a","text":"Personal Emergency Evacuation Plan"},{"key":"b","text":"Public Emergency Exit Point"},{"key":"c","text":"Portable Electrical Equipment Permit"},{"key":"d","text":"Planned Extinguisher Evaluation Programme"}],"correct_keys":["a"],"explanation":"A PEEP is a tailored plan for someone who needs help to evacuate.","sort_order":110},
      {"stem":"If a person's clothing catches fire, they should:","options":[{"key":"a","text":"Run to get help"},{"key":"b","text":"Stop, drop and roll"},{"key":"c","text":"Stand still and wave"},{"key":"d","text":"Fan the flames"}],"correct_keys":["b"],"explanation":"Stop, drop and roll smothers the flames.","sort_order":120},
      {"stem":"Good fire prevention housekeeping includes:","options":[{"key":"a","text":"Storing combustible waste in escape routes"},{"key":"b","text":"Keeping escape routes clear and not overloading sockets"},{"key":"c","text":"Propping fire doors open"},{"key":"d","text":"Ignoring faulty equipment"}],"correct_keys":["b"],"explanation":"Clear routes and safe electrics reduce fire risk and aid escape.","sort_order":130},
      {"stem":"The purpose of a fire drill is to:","options":[{"key":"a","text":"Test the alarm and practise safe evacuation"},{"key":"b","text":"Slow down the working day"},{"key":"c","text":"Replace the fire risk assessment"},{"key":"d","text":"Test the extinguishers"}],"correct_keys":["a"],"explanation":"Drills rehearse safe, orderly evacuation and test alarms/procedures.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 5. Safeguarding Adults (Level 2) ─────────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'safeguarding_adults_l2';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Safeguarding Adults Level 2 for staff in regular contact with adults at risk. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited. Always follow your local multi-agency safeguarding policy."},
      {"heading":"The Care Act 2014 and the six principles","body_md":"The Care Act 2014 is the statutory basis for adult safeguarding in England. An adult at risk is someone aged 18+ with care and support needs, who is experiencing or at risk of abuse or neglect, and who is unable to protect themselves because of those needs. The six safeguarding principles are: Empowerment, Prevention, Proportionality, Protection, Partnership and Accountability."},
      {"heading":"Types of abuse","body_md":"The Care Act sets out categories of abuse and neglect, including: physical, domestic, sexual, psychological/emotional, financial or material, modern slavery, discriminatory, organisational, neglect and acts of omission, and self-neglect. Abuse can be a single act or repeated, and can be deliberate or the result of ignorance."},
      {"heading":"Recognising and responding","body_md":"Indicators include unexplained injuries, sudden changes in behaviour or finances, poor care, fear of a particular person, or unmet needs. If someone discloses abuse, listen, stay calm, reassure them, and do NOT promise to keep it secret. Do not investigate or interview, and do not confront the alleged abuser."},
      {"heading":"Making it personal and raising a concern","body_md":"Making Safeguarding Personal means working with the person about the outcomes they want and respecting their wishes wherever possible. Preserve any evidence, record factually what you saw and were told, and report to your safeguarding lead / adult social care without delay. Whistleblowing protections apply if you raise concerns about poor or abusive practice."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"Which Act provides the statutory basis for adult safeguarding in England?","options":[{"key":"a","text":"Children Act 1989"},{"key":"b","text":"Care Act 2014"},{"key":"c","text":"Mental Health Act 1983"},{"key":"d","text":"Equality Act 2010"}],"correct_keys":["b"],"explanation":"The Care Act 2014 underpins adult safeguarding.","sort_order":10},
      {"stem":"How many statutory safeguarding principles are there under the Care Act?","options":[{"key":"a","text":"Four"},{"key":"b","text":"Five"},{"key":"c","text":"Six"},{"key":"d","text":"Ten"}],"correct_keys":["c"],"explanation":"Empowerment, Prevention, Proportionality, Protection, Partnership, Accountability — six principles.","sort_order":20},
      {"stem":"Which of the following is a Care Act safeguarding principle?","options":[{"key":"a","text":"Empowerment"},{"key":"b","text":"Secrecy"},{"key":"c","text":"Punishment"},{"key":"d","text":"Detention"}],"correct_keys":["a"],"explanation":"Empowerment is one of the six principles.","sort_order":30},
      {"stem":"An 'adult at risk' is someone who:","options":[{"key":"a","text":"Is over 65 only"},{"key":"b","text":"Has care and support needs, is experiencing or at risk of abuse, and cannot protect themselves"},{"key":"c","text":"Has any illness"},{"key":"d","text":"Lives alone"}],"correct_keys":["b"],"explanation":"This is the Care Act definition of an adult at risk.","sort_order":40},
      {"stem":"Which of the following IS a recognised category of abuse?","options":[{"key":"a","text":"Financial or material abuse"},{"key":"b","text":"Constructive feedback"},{"key":"c","text":"Reasonable adjustment"},{"key":"d","text":"Care planning"}],"correct_keys":["a"],"explanation":"Financial or material abuse is a Care Act category.","sort_order":50},
      {"stem":"Self-neglect is:","options":[{"key":"a","text":"Not a safeguarding concern"},{"key":"b","text":"A recognised category within adult safeguarding"},{"key":"c","text":"Only relevant to children"},{"key":"d","text":"Always the same as capacity"}],"correct_keys":["b"],"explanation":"Self-neglect is recognised in the Care Act categories.","sort_order":60},
      {"stem":"If an adult discloses abuse to you, you should:","options":[{"key":"a","text":"Promise to keep it a secret"},{"key":"b","text":"Listen, reassure, and explain you must pass the concern on"},{"key":"c","text":"Investigate it yourself"},{"key":"d","text":"Confront the alleged abuser"}],"correct_keys":["b"],"explanation":"Never promise secrecy; you must report. Do not investigate.","sort_order":70},
      {"stem":"When you have a safeguarding concern you should NOT:","options":[{"key":"a","text":"Record factually what you saw and heard"},{"key":"b","text":"Report to your safeguarding lead"},{"key":"c","text":"Investigate or interview the alleged abuser yourself"},{"key":"d","text":"Preserve any evidence"}],"correct_keys":["c"],"explanation":"Investigating is not your role; report and let the process take over.","sort_order":80},
      {"stem":"Making Safeguarding Personal means:","options":[{"key":"a","text":"Deciding outcomes for the person without asking them"},{"key":"b","text":"Working with the person on the outcomes they want"},{"key":"c","text":"Keeping the person out of the process"},{"key":"d","text":"Always removing the person from their home"}],"correct_keys":["b"],"explanation":"It is a person-led, outcomes-focused approach.","sort_order":90},
      {"stem":"An example of a possible sign of abuse is:","options":[{"key":"a","text":"Unexplained injuries or sudden fearfulness of a person"},{"key":"b","text":"A person enjoying a hobby"},{"key":"c","text":"Attending appointments"},{"key":"d","text":"Making an unwise but capacitous decision"}],"correct_keys":["a"],"explanation":"Unexplained injuries and fear of a person are potential indicators.","sort_order":100},
      {"stem":"Whistleblowing in a safeguarding context refers to:","options":[{"key":"a","text":"Gossiping about colleagues"},{"key":"b","text":"Raising concerns about poor or abusive practice, with legal protection"},{"key":"c","text":"Reporting only to the person responsible"},{"key":"d","text":"Keeping concerns to yourself"}],"correct_keys":["b"],"explanation":"Whistleblowing means raising concerns about wrongdoing, and is protected.","sort_order":110},
      {"stem":"Organisational abuse refers to:","options":[{"key":"a","text":"Poor care or neglectful practice within a service or institution"},{"key":"b","text":"A single financial theft"},{"key":"c","text":"A one-off medication error"},{"key":"d","text":"A disagreement between relatives"}],"correct_keys":["a"],"explanation":"Organisational abuse is neglect and poor practice within a care setting.","sort_order":120},
      {"stem":"You must never promise a person who discloses abuse that:","options":[{"key":"a","text":"You will listen to them"},{"key":"b","text":"You will keep it completely secret"},{"key":"c","text":"You will treat them with respect"},{"key":"d","text":"You will record what they told you"}],"correct_keys":["b"],"explanation":"You cannot guarantee confidentiality where there is a safeguarding concern.","sort_order":130},
      {"stem":"Preserving evidence in a suspected physical or sexual assault means:","options":[{"key":"a","text":"Cleaning the person and the area first"},{"key":"b","text":"Not disturbing the scene or items where possible, and reporting promptly"},{"key":"c","text":"Photographing everything and posting it"},{"key":"d","text":"Waiting until the next shift"}],"correct_keys":["b"],"explanation":"Avoid disturbing potential evidence and report without delay.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 6. Safeguarding Children & Young People (Level 2) ────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'safeguarding_children_l2';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Safeguarding Children and Young People Level 2 for staff in contact with children, young people and/or their parents/carers. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited. Follow your local safeguarding children partnership procedures."},
      {"heading":"The law and who is a child","body_md":"A child is anyone who has not yet reached their 18th birthday. Key legislation includes the Children Act 1989 and 2004, with statutory guidance in Working Together to Safeguard Children. The child's welfare is paramount, and safeguarding is everyone's responsibility."},
      {"heading":"The four categories of abuse","body_md":"The four categories are physical abuse, emotional abuse, sexual abuse, and neglect. Neglect is the persistent failure to meet a child's basic physical and/or psychological needs. Other concerns include child sexual and criminal exploitation (CSE/CCE), online abuse, domestic abuse and female genital mutilation (FGM)."},
      {"heading":"Recognising concerns","body_md":"Indicators can include unexplained or inconsistent injuries, developmental delay, poor hygiene, fearfulness, withdrawn behaviour, or a disclosure. Take any disclosure seriously: listen, do not lead or ask probing questions, reassure the child, and never promise to keep a secret. Record accurately using the child's own words."},
      {"heading":"Reporting and information sharing","body_md":"If you are worried a child is being harmed or is at risk, report to your safeguarding lead and/or children's social care without delay; in an emergency call 999. FGM on a girl under 18 must be reported. Concern for a child's welfare can override confidentiality: share information promptly, appropriately and proportionately to keep the child safe."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"For safeguarding purposes, a child is anyone who is:","options":[{"key":"a","text":"Under 16"},{"key":"b","text":"Under 18"},{"key":"c","text":"Under 21"},{"key":"d","text":"Under 13"}],"correct_keys":["b"],"explanation":"A child is anyone under 18.","sort_order":10},
      {"stem":"Which is key legislation for safeguarding children in England?","options":[{"key":"a","text":"Children Act 1989"},{"key":"b","text":"Care Act 2014"},{"key":"c","text":"Mental Capacity Act 2005"},{"key":"d","text":"Fire Safety Order 2005"}],"correct_keys":["a"],"explanation":"The Children Act 1989 (and 2004) is central to safeguarding children.","sort_order":20},
      {"stem":"What are the four categories of child abuse?","options":[{"key":"a","text":"Physical, emotional, sexual and neglect"},{"key":"b","text":"Financial, verbal, discriminatory and organisational"},{"key":"c","text":"Physical, self-neglect, modern slavery and domestic"},{"key":"d","text":"Neglect, bullying, truancy and theft"}],"correct_keys":["a"],"explanation":"The four categories are physical, emotional, sexual abuse and neglect.","sort_order":30},
      {"stem":"Neglect is best described as:","options":[{"key":"a","text":"A single argument between parents"},{"key":"b","text":"Persistent failure to meet a child's basic needs"},{"key":"c","text":"A child making a mistake"},{"key":"d","text":"A one-off late school pick-up"}],"correct_keys":["b"],"explanation":"Neglect is the persistent failure to meet basic physical/psychological needs.","sort_order":40},
      {"stem":"In safeguarding, the child's welfare is:","options":[{"key":"a","text":"Secondary to the parents' wishes"},{"key":"b","text":"Paramount"},{"key":"c","text":"Only relevant if there are injuries"},{"key":"d","text":"The responsibility of social workers alone"}],"correct_keys":["b"],"explanation":"The child's welfare is the paramount consideration.","sort_order":50},
      {"stem":"A child begins to disclose abuse to you. You should:","options":[{"key":"a","text":"Ask lots of probing, leading questions"},{"key":"b","text":"Listen, reassure, avoid leading questions, and not promise secrecy"},{"key":"c","text":"Promise to keep it just between you"},{"key":"d","text":"Tell them to talk to the alleged abuser"}],"correct_keys":["b"],"explanation":"Listen without leading, reassure, and never promise to keep it secret.","sort_order":60},
      {"stem":"Female genital mutilation (FGM) carried out on a girl under 18:","options":[{"key":"a","text":"Is a private family matter"},{"key":"b","text":"Must be reported"},{"key":"c","text":"Should be ignored"},{"key":"d","text":"Is only reported with parental consent"}],"correct_keys":["b"],"explanation":"There is a duty to report known FGM in a girl under 18.","sort_order":70},
      {"stem":"If you are concerned a child is at risk of harm, you should:","options":[{"key":"a","text":"Wait until you are certain before doing anything"},{"key":"b","text":"Report to your safeguarding lead and/or children's social care without delay"},{"key":"c","text":"Investigate the family yourself"},{"key":"d","text":"Only note it in a diary"}],"correct_keys":["b"],"explanation":"Report concerns promptly; do not wait for certainty.","sort_order":80},
      {"stem":"When you have a child safeguarding concern, you should NOT:","options":[{"key":"a","text":"Record what you observed"},{"key":"b","text":"Share information with the safeguarding lead"},{"key":"c","text":"Carry out your own investigation or interview"},{"key":"d","text":"Act promptly"}],"correct_keys":["c"],"explanation":"Investigating is for the statutory agencies, not you.","sort_order":90},
      {"stem":"Working Together to Safeguard Children is:","options":[{"key":"a","text":"Optional advice"},{"key":"b","text":"Statutory multi-agency safeguarding guidance"},{"key":"c","text":"A charity leaflet"},{"key":"d","text":"A local hospital policy only"}],"correct_keys":["b"],"explanation":"It is statutory guidance on multi-agency safeguarding of children.","sort_order":100},
      {"stem":"Regarding confidentiality when a child may be at risk:","options":[{"key":"a","text":"It can never be broken"},{"key":"b","text":"Concern for the child's welfare can override confidentiality"},{"key":"c","text":"Only a doctor may share information"},{"key":"d","text":"Information must never be shared with social care"}],"correct_keys":["b"],"explanation":"Child protection can justify appropriate, proportionate information sharing.","sort_order":110},
      {"stem":"Child sexual exploitation (CSE) may be indicated by:","options":[{"key":"a","text":"An older 'boyfriend', unexplained money/gifts, and going missing"},{"key":"b","text":"Doing homework on time"},{"key":"c","text":"Attending routine appointments"},{"key":"d","text":"Having age-appropriate friendships"}],"correct_keys":["a"],"explanation":"Unexplained gifts, a controlling older partner and going missing are CSE warning signs.","sort_order":120},
      {"stem":"Whose responsibility is safeguarding children?","options":[{"key":"a","text":"Only social workers"},{"key":"b","text":"Only the police"},{"key":"c","text":"Everyone who comes into contact with children"},{"key":"d","text":"Only teachers"}],"correct_keys":["c"],"explanation":"Safeguarding is everyone's responsibility.","sort_order":130},
      {"stem":"When recording a child's disclosure you should:","options":[{"key":"a","text":"Summarise it in your own interpretation"},{"key":"b","text":"Record accurately and factually, using the child's own words"},{"key":"c","text":"Only record it if there are visible injuries"},{"key":"d","text":"Delete it after reporting verbally"}],"correct_keys":["b"],"explanation":"Record factually in the child's own words as soon as possible.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 7. Information Governance / Data Security ─────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'information_governance';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Information Governance and Data Security Awareness for all staff handling personal or confidential data. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited. Follow your organisation's IG and data security policies and the NHS Data Security and Protection Toolkit (DSPT)."},
      {"heading":"The law","body_md":"Personal data is governed by the UK GDPR and the Data Protection Act 2018. Health data is 'special category' data requiring extra protection. Data must be handled lawfully, fairly, transparently, kept accurate, limited to what is necessary (data minimisation), kept no longer than needed, and kept secure. There is also a common-law duty of confidentiality."},
      {"heading":"Confidentiality and the Caldicott principles","body_md":"Share confidential information only on a 'need to know' basis, using the minimum necessary, and be aware of the duty to share where it is in the person's interest. Do not discuss patients in public areas or on social media. The Caldicott principles guide the safe and appropriate use of confidential health and care information."},
      {"heading":"Everyday data security","body_md":"Use strong, unique passwords and never share your login. Lock your screen whenever you leave your device. Send personal data only by secure/encrypted means, and check you are sending to the correct recipient. Dispose of confidential paper in confidential waste. Beware phishing emails and never click suspicious links."},
      {"heading":"Breaches and rights","body_md":"A data breach is any loss, theft, or unauthorised access, alteration or disclosure of personal data — for example a lost device, a mis-sent email, or a shared password. Report a suspected breach immediately to your line manager / Data Protection Officer; prompt reporting limits harm and meets legal duties. Individuals have rights over their data, including the right of access (a Subject Access Request)."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"Which laws primarily govern personal data in the UK?","options":[{"key":"a","text":"UK GDPR and the Data Protection Act 2018"},{"key":"b","text":"Care Act 2014"},{"key":"c","text":"Health and Safety at Work etc. Act 1974"},{"key":"d","text":"Equality Act 2010"}],"correct_keys":["a"],"explanation":"The UK GDPR and Data Protection Act 2018 govern personal data.","sort_order":10},
      {"stem":"Health records are an example of:","options":[{"key":"a","text":"Ordinary, low-risk data"},{"key":"b","text":"Special category personal data requiring extra protection"},{"key":"c","text":"Data that is not covered by data protection law"},{"key":"d","text":"Public information"}],"correct_keys":["b"],"explanation":"Health data is special category data needing extra safeguards.","sort_order":20},
      {"stem":"If you suspect a data breach (e.g. a lost device or mis-sent email) you should:","options":[{"key":"a","text":"Wait to see if anything happens"},{"key":"b","text":"Report it immediately to your manager / Data Protection Officer"},{"key":"c","text":"Try to fix it quietly and say nothing"},{"key":"d","text":"Only report it if a patient complains"}],"correct_keys":["b"],"explanation":"Report suspected breaches immediately to limit harm and meet legal duties.","sort_order":30},
      {"stem":"Sharing your system login with a trusted colleague is:","options":[{"key":"a","text":"Fine if they are staff"},{"key":"b","text":"Never acceptable"},{"key":"c","text":"Acceptable at night only"},{"key":"d","text":"Required in emergencies"}],"correct_keys":["b"],"explanation":"Logins are personal and must never be shared.","sort_order":40},
      {"stem":"When you leave your computer unattended you should:","options":[{"key":"a","text":"Leave it logged in for convenience"},{"key":"b","text":"Lock the screen"},{"key":"c","text":"Turn the monitor brightness down"},{"key":"d","text":"Ask a colleague to watch it"}],"correct_keys":["b"],"explanation":"Always lock your screen to prevent unauthorised access.","sort_order":50},
      {"stem":"The Caldicott principle of 'need to know' means:","options":[{"key":"a","text":"Everyone can see all patient data"},{"key":"b","text":"Access confidential information only where it is necessary for your role"},{"key":"c","text":"Only doctors may see records"},{"key":"d","text":"Data can be shared freely once anonymised names are removed"}],"correct_keys":["b"],"explanation":"Access should be limited to those who need it for the person's care.","sort_order":60},
      {"stem":"Discussing a named patient's details in a public corridor is:","options":[{"key":"a","text":"Acceptable if you are quiet"},{"key":"b","text":"A breach of confidentiality to avoid"},{"key":"c","text":"Fine among colleagues"},{"key":"d","text":"Only a problem on social media"}],"correct_keys":["b"],"explanation":"Confidential information must not be discussed where it can be overheard.","sort_order":70},
      {"stem":"When emailing personal data you should:","options":[{"key":"a","text":"Send it by any means quickly"},{"key":"b","text":"Use secure/encrypted email and verify the recipient"},{"key":"c","text":"CC everyone to be safe"},{"key":"d","text":"Put the details in the subject line"}],"correct_keys":["b"],"explanation":"Use secure channels and check the recipient before sending.","sort_order":80},
      {"stem":"A 'Subject Access Request' is:","options":[{"key":"a","text":"A request to delete all NHS records"},{"key":"b","text":"An individual's right to access the personal data held about them"},{"key":"c","text":"A staff request for overtime"},{"key":"d","text":"A police-only power"}],"correct_keys":["b"],"explanation":"A SAR is a person's right of access to their own personal data.","sort_order":90},
      {"stem":"The data minimisation principle means:","options":[{"key":"a","text":"Collect as much data as possible"},{"key":"b","text":"Collect and use only the personal data that is necessary"},{"key":"c","text":"Never collect any data"},{"key":"d","text":"Keep data forever"}],"correct_keys":["b"],"explanation":"Only the minimum necessary personal data should be processed.","sort_order":100},
      {"stem":"Confidential paper waste should be:","options":[{"key":"a","text":"Put in the general bin"},{"key":"b","text":"Disposed of via confidential waste / shredding"},{"key":"c","text":"Taken home"},{"key":"d","text":"Recycled with normal paper"}],"correct_keys":["b"],"explanation":"Confidential paper must go into confidential waste for secure destruction.","sort_order":110},
      {"stem":"A suspicious email asking you to click a link and confirm your password is likely:","options":[{"key":"a","text":"A phishing attempt to avoid and report"},{"key":"b","text":"A routine IT update to action"},{"key":"c","text":"Always safe if it looks official"},{"key":"d","text":"Best forwarded to all colleagues"}],"correct_keys":["a"],"explanation":"This is classic phishing — do not click; report it.","sort_order":120},
      {"stem":"The duty of confidentiality in health and care is:","options":[{"key":"a","text":"Only a workplace courtesy"},{"key":"b","text":"A legal and professional obligation"},{"key":"c","text":"Optional for support staff"},{"key":"d","text":"Waived once care ends"}],"correct_keys":["b"],"explanation":"Confidentiality is a legal (common-law) and professional duty.","sort_order":130},
      {"stem":"Strong password practice includes:","options":[{"key":"a","text":"Reusing one password everywhere"},{"key":"b","text":"Using a strong, unique password and not sharing it"},{"key":"c","text":"Writing it on a sticky note on the monitor"},{"key":"d","text":"Using your name and 1234"}],"correct_keys":["b"],"explanation":"Passwords should be strong, unique and never shared or left on display.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 8. Preventing Radicalisation (Prevent) ───────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'prevent_radicalisation';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Preventing Radicalisation (Prevent awareness) for health and care staff. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and is pending named-SME sign-off before it is treated as authoritative or accredited. Follow your organisation's Prevent policy and safeguarding lead arrangements."},
      {"heading":"What Prevent is","body_md":"Prevent is one of the four strands of the Government's counter-terrorism strategy, CONTEST (Prevent, Pursue, Protect, Prepare). The Prevent duty is a legal duty under the Counter-Terrorism and Security Act 2015 on specified authorities, including health. Its aim is to stop people from being drawn into terrorism, and it treats radicalisation as a safeguarding issue — supporting vulnerable people, not criminalising them."},
      {"heading":"Radicalisation and vulnerability","body_md":"Radicalisation is the process by which a person comes to support terrorism or extremist ideologies. It can affect anyone. Factors that may increase vulnerability include isolation, a sense of grievance or injustice, identity or personal crisis, and being groomed online. There is no single profile of a person at risk."},
      {"heading":"Extremism and British values","body_md":"Extremism is the vocal or active opposition to fundamental British values: democracy, the rule of law, individual liberty, and mutual respect and tolerance of those with different faiths and beliefs. Promoting these shared values is part of building resilience to radicalisation."},
      {"heading":"Raising a concern — Channel","body_md":"If you are concerned that someone is being drawn towards terrorism, raise it with your safeguarding/Prevent lead following local policy, as you would any safeguarding concern. Channel is a voluntary, confidential, multi-agency programme that provides tailored support to people identified as vulnerable to being drawn into terrorism. A referral is about support, not punishment."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"Prevent is one strand of which Government strategy?","options":[{"key":"a","text":"CONTEST"},{"key":"b","text":"CQC"},{"key":"c","text":"CSTF"},{"key":"d","text":"COSHH"}],"correct_keys":["a"],"explanation":"Prevent is part of CONTEST (Prevent, Pursue, Protect, Prepare).","sort_order":10},
      {"stem":"The Prevent duty is a legal duty under:","options":[{"key":"a","text":"The Counter-Terrorism and Security Act 2015"},{"key":"b","text":"The Care Act 2014"},{"key":"c","text":"The Data Protection Act 2018"},{"key":"d","text":"The Equality Act 2010"}],"correct_keys":["a"],"explanation":"The Prevent duty derives from the Counter-Terrorism and Security Act 2015.","sort_order":20},
      {"stem":"Radicalisation is treated primarily as:","options":[{"key":"a","text":"A criminal matter to be punished"},{"key":"b","text":"A safeguarding concern"},{"key":"c","text":"An immigration issue"},{"key":"d","text":"A private belief that is never relevant"}],"correct_keys":["b"],"explanation":"Prevent treats radicalisation as a safeguarding issue.","sort_order":30},
      {"stem":"What is Channel?","options":[{"key":"a","text":"A voluntary, multi-agency programme providing support to vulnerable people"},{"key":"b","text":"A prison programme"},{"key":"c","text":"A surveillance database"},{"key":"d","text":"A criminal charge"}],"correct_keys":["a"],"explanation":"Channel offers voluntary, tailored support to those at risk of radicalisation.","sort_order":40},
      {"stem":"If you are concerned a person is being drawn into terrorism, you should:","options":[{"key":"a","text":"Confront the person directly"},{"key":"b","text":"Raise it with your safeguarding/Prevent lead per local policy"},{"key":"c","text":"Do nothing unless you are certain"},{"key":"d","text":"Post about it on social media"}],"correct_keys":["b"],"explanation":"Raise concerns through your safeguarding/Prevent lead, like any safeguarding concern.","sort_order":50},
      {"stem":"Which of the following is a fundamental British value?","options":[{"key":"a","text":"The rule of law"},{"key":"b","text":"Support for one political party"},{"key":"c","text":"Loyalty to an employer"},{"key":"d","text":"Ownership of property"}],"correct_keys":["a"],"explanation":"The rule of law is one of the fundamental British values.","sort_order":60},
      {"stem":"Extremism is defined as:","options":[{"key":"a","text":"Holding any strong opinion"},{"key":"b","text":"Vocal or active opposition to fundamental British values"},{"key":"c","text":"Practising a religion"},{"key":"d","text":"Voting in an election"}],"correct_keys":["b"],"explanation":"Extremism is vocal or active opposition to fundamental British values.","sort_order":70},
      {"stem":"The aim of Prevent is to:","options":[{"key":"a","text":"Stop people from being drawn into terrorism"},{"key":"b","text":"Monitor everyone's religion"},{"key":"c","text":"Deport people"},{"key":"d","text":"Prosecute vulnerable people"}],"correct_keys":["a"],"explanation":"Prevent aims to safeguard people from being drawn into terrorism.","sort_order":80},
      {"stem":"Who can be affected by radicalisation?","options":[{"key":"a","text":"Only young men"},{"key":"b","text":"Only certain religious groups"},{"key":"c","text":"Anyone — there is no single profile"},{"key":"d","text":"Only people who have offended before"}],"correct_keys":["c"],"explanation":"Radicalisation can affect anyone; there is no single profile.","sort_order":90},
      {"stem":"Which may increase a person's vulnerability to radicalisation?","options":[{"key":"a","text":"A strong support network and stable identity"},{"key":"b","text":"Isolation, grievance or an identity crisis"},{"key":"c","text":"Regular employment"},{"key":"d","text":"Good mental health"}],"correct_keys":["b"],"explanation":"Isolation, grievance and identity crisis are recognised vulnerability factors.","sort_order":100},
      {"stem":"A Prevent/Channel referral is intended to:","options":[{"key":"a","text":"Punish the individual"},{"key":"b","text":"Provide early, supportive intervention"},{"key":"c","text":"Create a criminal record automatically"},{"key":"d","text":"Remove the person from the country"}],"correct_keys":["b"],"explanation":"A referral seeks to offer support, not punishment.","sort_order":110},
      {"stem":"WRAP training stands for:","options":[{"key":"a","text":"Workshop to Raise Awareness of Prevent"},{"key":"b","text":"Written Risk Assessment Protocol"},{"key":"c","text":"Ward Response and Action Plan"},{"key":"d","text":"Workplace Rights and Practices"}],"correct_keys":["a"],"explanation":"WRAP = Workshop to Raise Awareness of Prevent.","sort_order":120},
      {"stem":"Which organisations have a duty under Prevent?","options":[{"key":"a","text":"Only the police"},{"key":"b","text":"Specified authorities including health and education"},{"key":"c","text":"Only faith organisations"},{"key":"d","text":"No public bodies"}],"correct_keys":["b"],"explanation":"Specified authorities, including health and education, hold the Prevent duty.","sort_order":130},
      {"stem":"Promoting fundamental British values in care settings helps to:","options":[{"key":"a","text":"Build resilience against radicalisation"},{"key":"b","text":"Replace safeguarding policy"},{"key":"c","text":"Restrict people's beliefs"},{"key":"d","text":"Avoid the need to report concerns"}],"correct_keys":["a"],"explanation":"Shared values build resilience to radicalising influences.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 9. Resuscitation — Adult Basic Life Support (Level 2) ────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'bls_adult_l2';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Adult Basic Life Support Level 2 for clinical staff. This is an AI-DRAFTED, EDITABLE version reconstructed from CSTF norms and Resuscitation Council UK guidance and is pending named-SME sign-off before it is treated as authoritative or accredited. BLS requires annual PRACTICAL, hands-on training and assessment — this knowledge check does not replace it."},
      {"heading":"The chain of survival","body_md":"Survival from cardiac arrest depends on the chain of survival: early recognition and call for help, early CPR, early defibrillation, and post-resuscitation care. Every link matters and time is critical."},
      {"heading":"Initial assessment","body_md":"On finding a collapsed person: check for Danger and make the area safe; check Response by gently shaking the shoulders and asking loudly if they are all right; open the Airway with a head-tilt/chin-lift; and check Breathing — look, listen and feel for no more than 10 seconds. Occasional gasps (agonal breathing) are NOT normal breathing."},
      {"heading":"Calling for help and CPR","body_md":"If the person is unresponsive and not breathing normally, call 999 (and ask for an AED). Start chest compressions in the centre of the chest, compress to a depth of 5–6 cm at a rate of 100–120 per minute, allowing full recoil. Give 30 compressions to 2 rescue breaths, minimising interruptions."},
      {"heading":"Defibrillation, recovery position and choking","body_md":"Use an AED as soon as it arrives — switch it on and follow the voice prompts, applying the pads to the bare chest. If the person is unresponsive but breathing normally, place them in the recovery position and monitor. For choking with an ineffective cough: give up to 5 back blows, then up to 5 abdominal thrusts, repeating until relieved or the person becomes unresponsive (then start CPR)."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"What is the recommended chest compression rate for adult CPR?","options":[{"key":"a","text":"60–80 per minute"},{"key":"b","text":"100–120 per minute"},{"key":"c","text":"140–160 per minute"},{"key":"d","text":"As fast as possible"}],"correct_keys":["b"],"explanation":"The recommended rate is 100–120 compressions per minute.","sort_order":10},
      {"stem":"The recommended chest compression depth for an adult is:","options":[{"key":"a","text":"1–2 cm"},{"key":"b","text":"3–4 cm"},{"key":"c","text":"5–6 cm"},{"key":"d","text":"8–10 cm"}],"correct_keys":["c"],"explanation":"Compress the adult chest 5–6 cm deep.","sort_order":20},
      {"stem":"What is the compression-to-ventilation ratio in adult BLS (single/standard)?","options":[{"key":"a","text":"15:2"},{"key":"b","text":"30:2"},{"key":"c","text":"5:1"},{"key":"d","text":"10:2"}],"correct_keys":["b"],"explanation":"Adult BLS uses 30 compressions to 2 rescue breaths.","sort_order":30},
      {"stem":"On reaching a collapsed person, your FIRST action is to:","options":[{"key":"a","text":"Start compressions immediately"},{"key":"b","text":"Check for danger and make the area safe"},{"key":"c","text":"Give rescue breaths"},{"key":"d","text":"Fetch an AED"}],"correct_keys":["b"],"explanation":"Check for danger first — do not become a casualty yourself.","sort_order":40},
      {"stem":"How do you check for a response in a collapsed adult?","options":[{"key":"a","text":"Gently shake the shoulders and ask loudly if they are all right"},{"key":"b","text":"Splash water on their face"},{"key":"c","text":"Shout from across the room only"},{"key":"d","text":"Check their pulse for 2 minutes"}],"correct_keys":["a"],"explanation":"Gently shake the shoulders and ask loudly to check responsiveness.","sort_order":50},
      {"stem":"The person is unresponsive and not breathing normally. You should:","options":[{"key":"a","text":"Wait and watch for 5 minutes"},{"key":"b","text":"Call 999, ask for an AED, and start CPR"},{"key":"c","text":"Give them a drink"},{"key":"d","text":"Put them in the recovery position"}],"correct_keys":["b"],"explanation":"Call for help and begin CPR immediately.","sort_order":60},
      {"stem":"Where should you place your hands for chest compressions?","options":[{"key":"a","text":"On the upper abdomen"},{"key":"b","text":"In the centre of the chest (lower half of the breastbone)"},{"key":"c","text":"On the left side over the ribs"},{"key":"d","text":"On the neck"}],"correct_keys":["b"],"explanation":"Compress the centre of the chest, over the lower half of the sternum.","sort_order":70},
      {"stem":"When an AED arrives you should:","options":[{"key":"a","text":"Wait for a doctor before using it"},{"key":"b","text":"Switch it on and follow the voice prompts"},{"key":"c","text":"Only use it if trained as a paramedic"},{"key":"d","text":"Apply pads over clothing"}],"correct_keys":["b"],"explanation":"Turn the AED on and follow its spoken instructions; pads go on the bare chest.","sort_order":80},
      {"stem":"Occasional gasping (agonal breathing) in a collapsed person means:","options":[{"key":"a","text":"They are breathing normally — do not start CPR"},{"key":"b","text":"It is not normal breathing — start CPR"},{"key":"c","text":"They are asleep"},{"key":"d","text":"You should give them water"}],"correct_keys":["b"],"explanation":"Agonal gasps are not normal breathing; treat as cardiac arrest and start CPR.","sort_order":90},
      {"stem":"The first link in the chain of survival is:","options":[{"key":"a","text":"Post-resuscitation care"},{"key":"b","text":"Early recognition and call for help"},{"key":"c","text":"Defibrillation"},{"key":"d","text":"Advanced drugs"}],"correct_keys":["b"],"explanation":"Early recognition and calling for help is the first link.","sort_order":100},
      {"stem":"An unresponsive person who IS breathing normally should be:","options":[{"key":"a","text":"Given chest compressions"},{"key":"b","text":"Placed in the recovery position and monitored"},{"key":"c","text":"Left sitting upright"},{"key":"d","text":"Given rescue breaths only"}],"correct_keys":["b"],"explanation":"Use the recovery position and monitor breathing.","sort_order":110},
      {"stem":"Allowing full chest recoil between compressions is important because it:","options":[{"key":"a","text":"Wastes time"},{"key":"b","text":"Lets the heart refill, improving blood flow"},{"key":"c","text":"Is only needed in children"},{"key":"d","text":"Reduces the compression rate"}],"correct_keys":["b"],"explanation":"Full recoil allows the heart to refill, improving circulation.","sort_order":120},
      {"stem":"To maximise effectiveness of CPR you should:","options":[{"key":"a","text":"Take frequent long breaks"},{"key":"b","text":"Minimise interruptions to chest compressions"},{"key":"c","text":"Stop compressions to reassess every 30 seconds"},{"key":"d","text":"Compress slowly and shallowly"}],"correct_keys":["b"],"explanation":"Keep interruptions to compressions as short as possible.","sort_order":130},
      {"stem":"For an adult who is choking with an ineffective cough (still conscious), you should give:","options":[{"key":"a","text":"Chest compressions straight away"},{"key":"b","text":"Up to 5 back blows, then up to 5 abdominal thrusts"},{"key":"c","text":"A drink of water"},{"key":"d","text":"Nothing — tell them to wait"}],"correct_keys":["b"],"explanation":"For severe choking give up to 5 back blows then up to 5 abdominal thrusts, repeating.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 10. Oliver McGowan Mandatory Training (LD & Autism) Tier 2 ────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'oliver_mcgowan_t2';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Oliver McGowan Mandatory Training on Learning Disability and Autism, Tier 2, for staff who provide care and support. This is an AI-DRAFTED, EDITABLE version reconstructed from published policy and is pending named-SME sign-off before it is treated as authoritative or accredited. The Tier 2 programme also includes co-delivery with people with lived experience — this knowledge check does not replace the full programme."},
      {"heading":"Why this training exists","body_md":"The training is named after Oliver McGowan, whose death highlighted the need for staff to be better trained. It is a legal requirement under the Health and Care Act 2022 for CQC-registered health and social care providers. Tier 1 is for staff who need general awareness; Tier 2 is for staff who provide care and support to people with a learning disability and/or autistic people."},
      {"heading":"Reasonable adjustments and avoiding assumptions","body_md":"Under the Equality Act 2010, services must make reasonable adjustments so people with a learning disability and autistic people are not disadvantaged — for example longer appointments, easy-read information, a quieter environment, or a familiar carer present. Do not make assumptions about a person's capacity, understanding or quality of life."},
      {"heading":"Diagnostic overshadowing and health inequalities","body_md":"Diagnostic overshadowing is when a person's physical symptoms are wrongly attributed to their learning disability or autism, so a treatable illness is missed. People with a learning disability experience poorer health outcomes and, on average, die younger than the general population. Annual health checks and taking new or unexplained symptoms seriously help to reduce these inequalities."},
      {"heading":"Communication and co-production","body_md":"Autism is a lifelong developmental disability that affects how people communicate and experience the world; a learning disability affects the ability to learn new skills and understand complex information. Not everyone communicates verbally — adapt to the individual, allow processing time, and be mindful of sensory sensitivities. Work in partnership with the person and those who know them well: 'nothing about us without us'."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"The Oliver McGowan mandatory training is a legal requirement under:","options":[{"key":"a","text":"The Health and Care Act 2022"},{"key":"b","text":"The Care Act 2014"},{"key":"c","text":"The Mental Health Act 1983"},{"key":"d","text":"The Children Act 1989"}],"correct_keys":["a"],"explanation":"It is required under the Health and Care Act 2022.","sort_order":10},
      {"stem":"Tier 2 of the training is intended for:","options":[{"key":"a","text":"Staff who only need general awareness"},{"key":"b","text":"Staff who provide care and support to people with a learning disability and/or autistic people"},{"key":"c","text":"Members of the public"},{"key":"d","text":"Only senior managers"}],"correct_keys":["b"],"explanation":"Tier 2 is for staff who provide care and support.","sort_order":20},
      {"stem":"'Diagnostic overshadowing' means:","options":[{"key":"a","text":"Attributing physical symptoms to a person's learning disability/autism and missing a treatable illness"},{"key":"b","text":"Making a diagnosis very quickly"},{"key":"c","text":"Giving two diagnoses at once"},{"key":"d","text":"Overshadowing one clinician's opinion with another"}],"correct_keys":["a"],"explanation":"Diagnostic overshadowing wrongly attributes symptoms to LD/autism, missing illness.","sort_order":30},
      {"stem":"The legal basis for making reasonable adjustments is the:","options":[{"key":"a","text":"Equality Act 2010"},{"key":"b","text":"Data Protection Act 2018"},{"key":"c","text":"Fire Safety Order 2005"},{"key":"d","text":"Health and Safety at Work etc. Act 1974"}],"correct_keys":["a"],"explanation":"The Equality Act 2010 requires reasonable adjustments.","sort_order":40},
      {"stem":"An example of a reasonable adjustment is:","options":[{"key":"a","text":"A longer appointment and easy-read information"},{"key":"b","text":"Rushing the appointment"},{"key":"c","text":"Refusing a carer to attend"},{"key":"d","text":"Using more medical jargon"}],"correct_keys":["a"],"explanation":"Longer appointments and accessible information are reasonable adjustments.","sort_order":50},
      {"stem":"Autism is best described as:","options":[{"key":"a","text":"A mental illness that can be cured"},{"key":"b","text":"A lifelong developmental disability affecting communication and experience of the world"},{"key":"c","text":"A temporary condition"},{"key":"d","text":"A learning style choice"}],"correct_keys":["b"],"explanation":"Autism is a lifelong developmental disability.","sort_order":60},
      {"stem":"Regarding communication with autistic people and people with a learning disability:","options":[{"key":"a","text":"Everyone communicates verbally"},{"key":"b","text":"Not everyone communicates verbally — adapt to the individual"},{"key":"c","text":"You should always speak faster"},{"key":"d","text":"Written jargon is best"}],"correct_keys":["b"],"explanation":"Communication needs vary; adapt to the individual and allow processing time.","sort_order":70},
      {"stem":"People with a learning disability, compared with the general population, tend to:","options":[{"key":"a","text":"Have identical health outcomes"},{"key":"b","text":"Experience poorer health outcomes and die younger on average"},{"key":"c","text":"Never need annual health checks"},{"key":"d","text":"Require no reasonable adjustments"}],"correct_keys":["b"],"explanation":"They experience health inequalities and, on average, earlier death.","sort_order":80},
      {"stem":"Regarding a person's mental capacity you should:","options":[{"key":"a","text":"Assume they lack capacity because they have a learning disability"},{"key":"b","text":"Not make assumptions and assess capacity for the specific decision"},{"key":"c","text":"Ask a relative to decide everything"},{"key":"d","text":"Assume they always have full capacity for every decision"}],"correct_keys":["b"],"explanation":"Never assume capacity based on a diagnosis; assess for each decision.","sort_order":90},
      {"stem":"Sensory sensitivities (e.g. to noise or light) should be:","options":[{"key":"a","text":"Ignored"},{"key":"b","text":"Considered, e.g. offering a quieter environment"},{"key":"c","text":"Treated as attention-seeking"},{"key":"d","text":"Corrected by the person"}],"correct_keys":["b"],"explanation":"Adjust the environment for sensory needs, such as reducing noise/light.","sort_order":100},
      {"stem":"'Nothing about us without us' means:","options":[{"key":"a","text":"Decisions are made without the person"},{"key":"b","text":"People with lived experience are involved in decisions that affect them"},{"key":"c","text":"Only clinicians decide"},{"key":"d","text":"The person is excluded for their own good"}],"correct_keys":["b"],"explanation":"Co-production means involving people in decisions about them.","sort_order":110},
      {"stem":"Annual health checks for people with a learning disability help to:","options":[{"key":"a","text":"Identify and address health needs earlier"},{"key":"b","text":"Replace all other care"},{"key":"c","text":"Avoid reasonable adjustments"},{"key":"d","text":"Reduce staffing"}],"correct_keys":["a"],"explanation":"Annual health checks help detect and address health needs, reducing inequalities.","sort_order":120},
      {"stem":"A learning disability affects a person's:","options":[{"key":"a","text":"Ability to learn new skills and understand complex information"},{"key":"b","text":"Physical strength only"},{"key":"c","text":"Eyesight only"},{"key":"d","text":"Nothing at all"}],"correct_keys":["a"],"explanation":"A learning disability affects learning and understanding of complex information.","sort_order":130},
      {"stem":"When a person with a learning disability presents with new, unexplained symptoms you should:","options":[{"key":"a","text":"Assume it is due to their disability"},{"key":"b","text":"Take the symptoms seriously and investigate as you would for anyone"},{"key":"c","text":"Wait until the next annual check"},{"key":"d","text":"Ask them to manage it themselves"}],"correct_keys":["b"],"explanation":"Take symptoms seriously to avoid diagnostic overshadowing.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 11. Mental Capacity Act & DoLS ───────────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'mca_dols';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Mental Capacity Act (MCA) 2005 and Deprivation of Liberty Safeguards (DoLS) for staff supporting adults who may lack capacity. This is an AI-DRAFTED, EDITABLE version reconstructed from established practice and is pending named-SME sign-off before it is treated as authoritative or accredited. Follow your organisation's MCA/DoLS policy."},
      {"heading":"The five statutory principles","body_md":"The MCA 2005 has five principles: 1) assume a person has capacity unless proven otherwise; 2) support people to make their own decisions before concluding they cannot; 3) an unwise decision does not by itself mean a person lacks capacity; 4) anything done for a person who lacks capacity must be in their best interests; and 5) choose the least restrictive option. The MCA applies to people aged 16 and over."},
      {"heading":"Assessing capacity","body_md":"Capacity is decision-specific and time-specific. The two-stage test asks: is there an impairment of, or disturbance in, the functioning of the mind or brain; and, because of that, is the person unable to make the specific decision at this time? A person is unable to decide if they cannot understand, retain, use or weigh the relevant information, or communicate their decision."},
      {"heading":"Best interests and least restriction","body_md":"If a person lacks capacity for a decision, act in their best interests: consider their past and present wishes, feelings, beliefs and values, and consult those close to them where practical. Always choose the option that is least restrictive of the person's rights and freedoms. An Independent Mental Capacity Advocate (IMCA) may be instructed where a person has no one appropriate to consult for serious decisions."},
      {"heading":"Deprivation of Liberty Safeguards","body_md":"DoLS provide legal authorisation where a person who lacks capacity is deprived of their liberty in a hospital or care home to keep them safe. The 'acid test' from case law: the person is under continuous supervision and control AND is not free to leave. A deprivation of liberty must be authorised — it cannot simply be assumed to be acceptable because it is in the person's best interests."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"In which year was the Mental Capacity Act enacted?","options":[{"key":"a","text":"1998"},{"key":"b","text":"2005"},{"key":"c","text":"2014"},{"key":"d","text":"2022"}],"correct_keys":["b"],"explanation":"The Mental Capacity Act 2005.","sort_order":10},
      {"stem":"How many statutory principles does the MCA have?","options":[{"key":"a","text":"Three"},{"key":"b","text":"Four"},{"key":"c","text":"Five"},{"key":"d","text":"Six"}],"correct_keys":["c"],"explanation":"The MCA has five statutory principles.","sort_order":20},
      {"stem":"The starting point of the MCA is that:","options":[{"key":"a","text":"Everyone lacks capacity until proven otherwise"},{"key":"b","text":"A person is assumed to have capacity unless proven otherwise"},{"key":"c","text":"Only doctors have capacity to decide"},{"key":"d","text":"Capacity depends on age alone"}],"correct_keys":["b"],"explanation":"Assume capacity unless it is established otherwise.","sort_order":30},
      {"stem":"A person makes what you think is an unwise decision. This means:","options":[{"key":"a","text":"They automatically lack capacity"},{"key":"b","text":"They do not lack capacity for that reason alone"},{"key":"c","text":"You should overrule them"},{"key":"d","text":"They must be assessed by a psychiatrist"}],"correct_keys":["b"],"explanation":"An unwise decision does not, by itself, mean a person lacks capacity.","sort_order":40},
      {"stem":"The two-stage capacity test first asks whether there is:","options":[{"key":"a","text":"An impairment of, or disturbance in, the functioning of the mind or brain"},{"key":"b","text":"A physical injury"},{"key":"c","text":"A language barrier only"},{"key":"d","text":"A family disagreement"}],"correct_keys":["a"],"explanation":"Stage one asks about an impairment/disturbance of the mind or brain.","sort_order":50},
      {"stem":"To have capacity for a decision, a person must be able to understand, retain, use/weigh the information AND:","options":[{"key":"a","text":"Communicate their decision"},{"key":"b","text":"Agree with the clinician"},{"key":"c","text":"Write it down"},{"key":"d","text":"Have a relative present"}],"correct_keys":["a"],"explanation":"They must also be able to communicate their decision.","sort_order":60},
      {"stem":"Mental capacity is:","options":[{"key":"a","text":"A fixed, permanent status"},{"key":"b","text":"Decision-specific and time-specific"},{"key":"c","text":"The same for all decisions"},{"key":"d","text":"Determined only by diagnosis"}],"correct_keys":["b"],"explanation":"Capacity is assessed for a specific decision at a specific time.","sort_order":70},
      {"stem":"If a person lacks capacity for a decision, any action taken must be:","options":[{"key":"a","text":"In the best interests of the care provider"},{"key":"b","text":"In the person's best interests"},{"key":"c","text":"The cheapest option"},{"key":"d","text":"Whatever the family prefers"}],"correct_keys":["b"],"explanation":"Decisions for someone lacking capacity must be in their best interests.","sort_order":80},
      {"stem":"When acting for someone who lacks capacity you should choose the option that is:","options":[{"key":"a","text":"Most restrictive"},{"key":"b","text":"Least restrictive of their rights and freedoms"},{"key":"c","text":"Easiest for staff"},{"key":"d","text":"Quickest"}],"correct_keys":["b"],"explanation":"Choose the least restrictive option.","sort_order":90},
      {"stem":"The DoLS 'acid test' is that the person is:","options":[{"key":"a","text":"Under continuous supervision and control AND not free to leave"},{"key":"b","text":"Simply in hospital"},{"key":"c","text":"Refusing medication"},{"key":"d","text":"Over 65"}],"correct_keys":["a"],"explanation":"The acid test: continuous supervision and control, and not free to leave.","sort_order":100},
      {"stem":"An IMCA is:","options":[{"key":"a","text":"An Independent Mental Capacity Advocate"},{"key":"b","text":"An Internal Medication Compliance Auditor"},{"key":"c","text":"A type of court order"},{"key":"d","text":"A hospital ward"}],"correct_keys":["a"],"explanation":"An IMCA is an Independent Mental Capacity Advocate.","sort_order":110},
      {"stem":"A deprivation of liberty in a care home or hospital must be:","options":[{"key":"a","text":"Assumed acceptable if it is in best interests"},{"key":"b","text":"Legally authorised"},{"key":"c","text":"Decided by the family alone"},{"key":"d","text":"Never allowed under any circumstances"}],"correct_keys":["b"],"explanation":"A deprivation of liberty requires lawful authorisation (e.g. DoLS).","sort_order":120},
      {"stem":"From what age does the Mental Capacity Act generally apply?","options":[{"key":"a","text":"18"},{"key":"b","text":"16"},{"key":"c","text":"21"},{"key":"d","text":"14"}],"correct_keys":["b"],"explanation":"The MCA applies to people aged 16 and over.","sort_order":130},
      {"stem":"Best interests decision-making should include:","options":[{"key":"a","text":"Ignoring the person's past wishes"},{"key":"b","text":"Considering the person's wishes, feelings, beliefs and values, and consulting those close to them"},{"key":"c","text":"Only the clinician's view"},{"key":"d","text":"Whatever is most convenient"}],"correct_keys":["b"],"explanation":"Best interests must weigh the person's wishes/values and consult relevant people.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;

-- ── 12. Sepsis Awareness & Recognition ───────────────────────────────────────
do $$
declare v_module uuid; v_version uuid; q jsonb;
begin
  select id into v_module from candidate.training_modules where code = 'sepsis';
  if v_module is not null and not exists (select 1 from candidate.module_versions where module_id = v_module) then
    v_version := candidate.save_module_version(v_module, $c$[
      {"heading":"About this module","body_md":"Sepsis Awareness and Recognition for clinical and patient-facing staff. This is an AI-DRAFTED, EDITABLE version reconstructed from established clinical guidance (NICE/UK Sepsis Trust/Resuscitation practice) and is pending named-SME sign-off before it is treated as authoritative or accredited. Always follow your local sepsis screening and escalation protocol."},
      {"heading":"What sepsis is","body_md":"Sepsis is a life-threatening condition that arises when the body's response to an infection injures its own tissues and organs. It is a medical emergency: it can follow any infection, deteriorate rapidly, and cause organ dysfunction, shock and death. Early recognition and treatment save lives."},
      {"heading":"Recognising sepsis","body_md":"Think 'could this be sepsis?' in anyone with a likely or confirmed infection who is deteriorating. Warning signs in adults include new confusion or slurred speech, extreme shivering or muscle pain, passing little or no urine, severe breathlessness, a fast heart rate, and skin that is mottled, pale or discoloured. Use a structured tool such as NEWS2 (National Early Warning Score 2) to identify and track deterioration."},
      {"heading":"Higher-risk groups","body_md":"Some people are at higher risk, including the very young and very old, pregnant or recently pregnant women, people with weakened immune systems (for example due to chemotherapy or diabetes), those who have had recent surgery, and people with indwelling lines or catheters. Signs can be subtler in these groups — maintain a high index of suspicion."},
      {"heading":"Acting on sepsis — escalate","body_md":"Sepsis is time-critical. If you suspect it, escalate immediately to a senior clinician; do not wait. In hospital, the 'Sepsis Six' bundle (give oxygen, take blood cultures, give IV antibiotics, give IV fluids, check lactate, and monitor urine output) should be delivered within one hour of recognition. Every hour of delay in treatment increases the risk of harm."}
    ]$c$::jsonb, null, true, 'claude-opus-4-8');

    for q in select value from jsonb_array_elements($qq$[
      {"stem":"Sepsis is best described as:","options":[{"key":"a","text":"A mild reaction to a cold"},{"key":"b","text":"A life-threatening response to infection that injures the body's own organs"},{"key":"c","text":"A type of cancer"},{"key":"d","text":"A skin allergy"}],"correct_keys":["b"],"explanation":"Sepsis is the body's dysregulated, life-threatening response to infection.","sort_order":10},
      {"stem":"Sepsis should be treated as:","options":[{"key":"a","text":"A routine problem that can wait"},{"key":"b","text":"A medical emergency"},{"key":"c","text":"Something only relevant in intensive care"},{"key":"d","text":"A minor infection"}],"correct_keys":["b"],"explanation":"Sepsis is a time-critical medical emergency.","sort_order":20},
      {"stem":"The 'Sepsis Six' bundle should ideally be delivered within:","options":[{"key":"a","text":"1 hour of recognition"},{"key":"b","text":"6 hours"},{"key":"c","text":"12 hours"},{"key":"d","text":"24 hours"}],"correct_keys":["a"],"explanation":"The Sepsis Six should be completed within one hour of recognition.","sort_order":30},
      {"stem":"Which is a red-flag sign of sepsis in an adult?","options":[{"key":"a","text":"New confusion or slurred speech"},{"key":"b","text":"Feeling slightly tired"},{"key":"c","text":"A mild headache alone"},{"key":"d","text":"A single sneeze"}],"correct_keys":["a"],"explanation":"New confusion/slurred speech is a recognised sepsis red flag.","sort_order":40},
      {"stem":"Which scoring tool is commonly used to identify and track deterioration in adults?","options":[{"key":"a","text":"NEWS2 (National Early Warning Score 2)"},{"key":"b","text":"BMI"},{"key":"c","text":"GCS only"},{"key":"d","text":"TILE"}],"correct_keys":["a"],"explanation":"NEWS2 is widely used to detect and track deterioration, including sepsis.","sort_order":50},
      {"stem":"A useful prompt when a patient with infection is deteriorating is to:","options":[{"key":"a","text":"Ask 'could this be sepsis?'"},{"key":"b","text":"Assume it is anxiety"},{"key":"c","text":"Wait until the next ward round"},{"key":"d","text":"Send them home"}],"correct_keys":["a"],"explanation":"Actively asking 'could this be sepsis?' prompts early recognition.","sort_order":60},
      {"stem":"Which group is at higher risk of sepsis?","options":[{"key":"a","text":"People with weakened immune systems"},{"key":"b","text":"Only teenagers"},{"key":"c","text":"Only people with no medical history"},{"key":"d","text":"Only smokers"}],"correct_keys":["a"],"explanation":"Immunocompromised people (and the very young/old, pregnant, post-surgical) are higher risk.","sort_order":70},
      {"stem":"If you suspect sepsis you should:","options":[{"key":"a","text":"Escalate immediately to a senior clinician"},{"key":"b","text":"Wait a few hours to see if it improves"},{"key":"c","text":"Reassure the patient and take no action"},{"key":"d","text":"Only record it in the notes"}],"correct_keys":["a"],"explanation":"Escalate straight away — sepsis is time-critical.","sort_order":80},
      {"stem":"Sepsis can develop from:","options":[{"key":"a","text":"Any infection"},{"key":"b","text":"Only chest infections"},{"key":"c","text":"Only wounds"},{"key":"d","text":"Only urinary infections"}],"correct_keys":["a"],"explanation":"Any infection can lead to sepsis.","sort_order":90},
      {"stem":"Passing little or no urine in a deteriorating patient may indicate:","options":[{"key":"a","text":"Nothing of concern"},{"key":"b","text":"A possible sign of sepsis / organ dysfunction"},{"key":"c","text":"Good hydration"},{"key":"d","text":"Normal recovery"}],"correct_keys":["b"],"explanation":"Reduced urine output is a recognised warning sign of sepsis.","sort_order":100},
      {"stem":"Which is part of the 'Sepsis Six'?","options":[{"key":"a","text":"Give IV antibiotics"},{"key":"b","text":"Discharge the patient"},{"key":"c","text":"Withhold all fluids"},{"key":"d","text":"Delay blood cultures for a day"}],"correct_keys":["a"],"explanation":"Giving IV antibiotics is one of the Sepsis Six interventions.","sort_order":110},
      {"stem":"Mottled or discoloured skin in an unwell patient with infection should:","options":[{"key":"a","text":"Be ignored"},{"key":"b","text":"Raise concern about sepsis and prompt escalation"},{"key":"c","text":"Be treated with moisturiser"},{"key":"d","text":"Only matter in children"}],"correct_keys":["b"],"explanation":"Mottled/discoloured skin is a red flag warranting escalation.","sort_order":120},
      {"stem":"Delaying treatment of sepsis:","options":[{"key":"a","text":"Has no effect on outcome"},{"key":"b","text":"Increases the risk of harm and death"},{"key":"c","text":"Improves recovery"},{"key":"d","text":"Is recommended to observe progress"}],"correct_keys":["b"],"explanation":"Every hour of delay increases the risk of harm; early treatment saves lives.","sort_order":130},
      {"stem":"In higher-risk groups such as the elderly or immunocompromised, sepsis signs may be:","options":[{"key":"a","text":"Always obvious"},{"key":"b","text":"Subtler, so a high index of suspicion is needed"},{"key":"c","text":"Absent, so no monitoring is needed"},{"key":"d","text":"Irrelevant"}],"correct_keys":["b"],"explanation":"Signs can be subtle in vulnerable groups; stay highly alert.","sort_order":140}
    ]$qq$::jsonb) loop
      perform candidate.add_training_question(v_version, q->>'stem', q->'options', q->'correct_keys', q->>'explanation', (q->>'sort_order')::int);
    end loop;
  end if;
end $$;
